    "whyItMatters": "कई ऑनलाइन उपकरण गलत दावा करते हैं कि वे निट्स या डेल्टा ई सटीकता मापते हैं; वास्तविक सीमाओं को जानने से भ्रामक निदान से बचा जा सकता है।",
